CREATE FUNCTION advance_seat_formal_version() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW.formal_version := OLD.formal_version + 1;
    RETURN NEW;
END;
$$

DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM seats WHERE zone_id IS NULL) THEN
        RAISE EXCEPTION 'Every legacy seat must map to exactly one venue Zone';
    END IF;
END $$

DO $$
DECLARE
    legacy RECORD;
    suffix INTEGER;
    candidate TEXT;
BEGIN
    FOR legacy IN SELECT * FROM phase17_legacy_zones
                  WHERE raw_zone ~ '^[[:space:]]*$' ORDER BY venue_id, position
    LOOP
        suffix := 0;
        candidate := '未命名区域';
        WHILE EXISTS (SELECT 1 FROM venue_zones WHERE venue_id=legacy.venue_id AND name=candidate)
        LOOP
            suffix := suffix + 1;
            candidate := '未命名区域-' || suffix::text;
        END LOOP;
        INSERT INTO venue_zones (id, venue_id, code, name, sort_order)
        VALUES (legacy.id, legacy.venue_id, 'LEGACY_' || legacy.position::text, candidate, legacy.position);
    END LOOP;
END $$

DO $$
DECLARE legacy TEXT := current_setting('ticketing.legacy_payment_currency', true);
BEGIN
    IF EXISTS (SELECT 1 FROM payment_attempts) THEN
        IF legacy IS NULL OR legacy !~ '^[a-z]{3}$' THEN
            RAISE EXCEPTION 'Confirm historical single currency and SET ticketing.legacy_payment_currency in this session';
        END IF;
        UPDATE payment_attempts SET currency = legacy;
        UPDATE refunds r SET currency = a.currency FROM payment_attempts a
        WHERE a.id = r.payment_attempt_id AND a.order_id = r.order_id;
    END IF;
    IF EXISTS (SELECT 1 FROM payment_attempts WHERE currency IS NULL)
       OR EXISTS (SELECT 1 FROM refunds WHERE currency IS NULL) THEN
        RAISE EXCEPTION 'Historical currency mapping incomplete';
    END IF;
END $$

CREATE FUNCTION enqueue_seat_availability_change() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO seat_availability_outbox(session_id, session_seat_id, formal_status, formal_version)
    VALUES (NEW.session_id, NEW.id, NEW.status, NEW.formal_version);
    RETURN NEW;
END;
$$
